import sys
from collections import defaultdict

def read_input():
    import sys
    input = sys.stdin.read
    data = input().split()

    index = 0
    t = int(data[index])
    index += 1

    results = []

    for _ in range(t):
        n = int(data[index])
        index += 1

        edges = []
        for _ in range(n - 1):
            u = int(data[index])
            v = int(data[index + 1])
            index += 2
            edges.append((u, v))

        results.append(solve(n, edges))

    for result in results:
        print(" ".join(map(str, result)))

def solve(n, edges):
    # Create adjacency list
    adj_list = defaultdict(list)
    for u, v in edges:
        adj_list[u].append(v)
        adj_list[v].append(u)

    # Function to check if a node can be a starting point for Eikooc
    def can_win(start):
        visited = set()
        stack = [start]
        while stack:
            node = stack.pop()
            visited.add(node)
            for neighbor in adj_list[node]:
                if neighbor not in visited and (node ^ neighbor) <= min(node, neighbor):
                    stack.append(neighbor)
        return len(visited) == n

    # Try to find a relabeling that maximizes the number of winning starting points
    for i in range(1, n + 1):
        if can_win(i):
            return list(range(1, n + 1))

    # If no such relabeling is found, return the identity permutation
    return list(range(1, n + 1))

read_input()
